import{_ as t,o as r,c as e,ag as o}from"./chunks/framework.CAXxHpAX.js";const g=JSON.parse('{"title":"408 统考计算机组成原理 (Computer Organization) —— 知识库总览","description":"","frontmatter":{},"headers":[],"relativePath":"计算机组成原理/index.md","filePath":"计算机组成原理/index.md","lastUpdated":1777124994000}'),l={name:"计算机组成原理/index.md"};function i(n,a,s,h,_,d){return r(),e("div",null,[...a[0]||(a[0]=[o('<h1 id="_408-统考计算机组成原理-computer-organization-——-知识库总览" tabindex="-1">408 统考计算机组成原理 (Computer Organization) —— 知识库总览 <a class="header-anchor" href="#_408-统考计算机组成原理-computer-organization-——-知识库总览" aria-label="Permalink to &quot;408 统考计算机组成原理 (Computer Organization) —— 知识库总览&quot;">​</a></h1><blockquote><p>本资料库汇集了 408 考研《计算机组成原理》科目的全部核心知识点、重点难点梳理、错题复盘以及思维导图，旨在为冲刺阶段提供全面、系统、无错漏的背诵与查阅资料。</p></blockquote><hr><h2 id="📂-目录结构与内容说明" tabindex="-1">📂 目录结构与内容说明 <a class="header-anchor" href="#📂-目录结构与内容说明" aria-label="Permalink to &quot;📂 目录结构与内容说明&quot;">​</a></h2><p>本模块根据 408 官方大纲划分为核心的 7 个章节，并附加了强化冲刺所需的高频考点总结与思维导图提纲。</p><h3 id="核心教材笔记" tabindex="-1">核心教材笔记 <a class="header-anchor" href="#核心教材笔记" aria-label="Permalink to &quot;核心教材笔记&quot;">​</a></h3><ul><li><strong><a href="./01_计算机系统概述.html">01_计算机系统概述</a></strong>: 冯·诺依曼架构、计算机性能评测指标 (字长, 主频, CPI, MIPS) 等核心基础。</li><li><strong><a href="./02_数据的表示和运算.html">02_数据的表示和运算</a></strong>: 原码/补码/反码/移码体系、IEEE 754 浮点数标准、加减乘除底层运算器 (ALU) 运转逻辑。</li><li><strong><a href="./03_存储系统.html">03_存储系统</a></strong>: SRAM/DRAM、主存交叉编址、Cache 映射机制与替换算法、虚拟存储器 (页表/TLB)。<strong>【极高频考点】</strong></li><li><strong><a href="./04_指令系统.html">04_指令系统</a></strong>: CISC 与 RISC 分析、寻址方式深刻剖析、指令格式设计。</li><li><strong><a href="./05_中央处理器.html">05_中央处理器</a></strong>: 数据通路、硬布线与微程序控制器、指令流水线技术及冒险解决 (数据冲突、控制冲突)。<strong>【极高频考点】</strong></li><li><strong><a href="./06_总线.html">06_总线</a></strong>: 总线分类、总线特性、总线仲裁 (集中式与分布式)、总线操作及时序。</li><li><strong><a href="./07_输入输出系统.html">07_输入输出系统</a></strong>: I/O 接口、程序查询方式、中断系统机制、DMA 控制器及工作过程。</li></ul><h3 id="冲刺提分与框架" tabindex="-1">冲刺提分与框架 <a class="header-anchor" href="#冲刺提分与框架" aria-label="Permalink to &quot;冲刺提分与框架&quot;">​</a></h3><ul><li><strong><a href="./08_考频与重难点总结.html">08_考频与重难点总结</a></strong>: 包含了历年高频考点统计（如数据运算与强制类型转换、Cache映射计算、流水线计算）、易错核心公式及解题技巧。</li></ul><h3 id="资源文件" tabindex="-1">资源文件 <a class="header-anchor" href="#资源文件" aria-label="Permalink to &quot;资源文件&quot;">​</a></h3><ul><li><code>images/</code>: 存放了各个 MD 文件引用的插图、数据通路解析图、真题分析图，已全部就地化，支持离线或防挂图本地查看。</li><li><code>09_计算机组成原理大纲_思维导图.xmind</code> &amp; <code>09_计算机组成原理大纲_思维导图.png</code>: 提供全书的结构俯瞰视角。</li></ul><hr><h2 id="💡-备考建议" tabindex="-1">💡 备考建议 <a class="header-anchor" href="#💡-备考建议" aria-label="Permalink to &quot;💡 备考建议&quot;">​</a></h2><ol><li><strong>宏观把控</strong>: 计算机组成原理知识点较硬、注重底层。在阅读各章前，建议先打开 <code>09_计算机组成原理大纲_思维导图.png</code> 看清该章节在整个计算机硬件组织中的位置。</li><li><strong>重点突破</strong>: 『03_存储系统』与『05_中央处理器』每年必出计算类综合大题，在看这两节时需多加笔算验证。</li><li><strong>结合代码</strong>: 组成原理部分强调的类型转换、位运算与数据溢出，与实际的 C 代码息息相关，请结合代码层面理解它的执行过程！</li></ol>',14)])])}const m=t(l,[["render",i]]);export{g as __pageData,m as default};
